class Solution:
    def canCarryAll(self, capacity: int, trips: List[List[int]]) -> bool:
        last = max(t[2] for t in trips)
        for m in range(last + 1):
            load = sum(p for p, a, b in trips if a <= m < b)
            if load > capacity:
                return False
        return True

