class Solution {
    public boolean canCarryAll(int capacity, int[][] trips) {
        int last = 0;
        for (int[] t : trips) last = Math.max(last, t[2]);
        for (int m = 0; m <= last; m++) {
            int load = 0;
            for (int[] t : trips) if (t[1] <= m && m < t[2]) load += t[0];
            if (load > capacity) return false;
        }
        return true;
    }
}

