class Solution {
    public boolean canCarryAll(int capacity, int[][] trips) {
        int[][] events = new int[2 * trips.length][];
        for (int i = 0; i < trips.length; i++) {
            events[2 * i] = new int[] {trips[i][1], trips[i][0]};
            events[2 * i + 1] = new int[] {trips[i][2], -trips[i][0]};
        }
        Arrays.sort(events, (x, y) -> x[0] != y[0] ? Integer.compare(x[0], y[0]) : Integer.compare(x[1], y[1]));
        int load = 0;
        for (int[] e : events) {
            load += e[1];
            if (load > capacity) return false;
        }
        return true;
    }
}

