typedef struct { int mark, change; } Event;

static int byMarkThenChange(const void* a, const void* b) {
    const Event* x = a;
    const Event* y = b;
    if (x->mark != y->mark) return (x->mark > y->mark) - (x->mark < y->mark);
    return (x->change > y->change) - (x->change < y->change);
}

bool canCarryAll(int capacity, int** trips, int tripsSize, int* tripsColSize) {
    Event* events = malloc(2 * tripsSize * sizeof(Event));
    for (int i = 0; i < tripsSize; i++) {
        events[2 * i] = (Event) {trips[i][1], trips[i][0]};
        events[2 * i + 1] = (Event) {trips[i][2], -trips[i][0]};
    }
    qsort(events, 2 * tripsSize, sizeof(Event), byMarkThenChange);
    int load = 0;
    bool ok = true;
    for (int i = 0; i < 2 * tripsSize && ok; i++) {
        load += events[i].change;
        if (load > capacity) ok = false;
    }
    free(events);
    return ok;
}

