bool canCarryAll(int capacity, int** trips, int tripsSize, int* tripsColSize) {
    int last = 0;
    for (int i = 0; i < tripsSize; i++) if (trips[i][2] > last) last = trips[i][2];
    int* change = calloc(last + 1, sizeof(int));
    for (int i = 0; i < tripsSize; i++) {
        change[trips[i][1]] += trips[i][0];
        change[trips[i][2]] -= trips[i][0];
    }
    int load = 0;
    bool ok = true;
    for (int m = 0; m <= last && ok; m++) {
        load += change[m];
        if (load > capacity) ok = false;
    }
    free(change);
    return ok;
}
